head.script:
scwin._checkError = function() {
    var log = WebSquare.logger.getLog();
    return log.indexOf("Cannot read property 'documentElement' of null") == -1;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 create버튼을 클릭하고 마우스+우클릭으로 로그보기를 실행한다.
    //1. After running the sample file, click the create button and execute mouse-click view of the log.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 로그가 정상적으로 보여진다.(이전에는 특수문자가 title에 있을 경우 에러로그발생함) 또한, windowsContainer title의 값이 정상적으로 보여진다.(하나 > 둘둘)
    //1. The log is displayed normally. (In the past, if the special character is in title, an error log occurs.) Also, the value of the windowsContainer title is shown normally (one> two)                
    WebSquare.wUnit.addCommand("assert", "scwin._checkError()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('windowContainer2_subWindow0_header_title').innerText == '하나 > 둘둘'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //debugger;
    //WebSquareLang.WindowContainer_maxNum_warning = "min";
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 07-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
